import{_ as t,a,o as i,a6 as n}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Appearance","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/appearance/index.md","filePath":"api/rest-api/admin/appearance/index.md","lastUpdated":1789385991000}'),s={name:"api/rest-api/admin/appearance/index.md"};function r(d,e,o,h,c,p){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h1><p>Appearance is where a store chooses how the storefront looks. It holds two things: the themes the installation has, and the sections each channel draws inside the theme it runs.</p><h2 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h2><p>A theme is a package of storefront templates and assets. The installation knows about two kinds — the ones installed on the server, and the ones listed as available to install. A theme is activated per channel, so two channels can run different themes at the same time.</p><p>Activating a theme on a channel does not delete anything. Sections built for the channel&#39;s previous theme stay in the database and simply stop being drawn, and they come back if the channel is pointed at that theme again. The impact endpoint reports how many sections a channel would leave behind before anything is written.</p><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><p>A section is one block of the storefront page — a carousel, a static block, the footer link set. Each section belongs to one theme and one channel, and its content is stored per locale.</p><p>Six types exist: <code>image_carousel</code>, <code>product_carousel</code>, <code>category_carousel</code>, <code>footer_links</code>, <code>static_content</code> and <code>services_content</code>. A type decides the fields a section carries, which the fields endpoint returns as a schema.</p><p>Two rules the storefront depends on:</p><ul><li>A channel can have at most one <code>footer_links</code> section, because the storefront has one footer to draw it in. Creating or switching a second one is rejected.</li><li><code>footer_links</code> is always drawn last, so a reorder that puts it anywhere else has it moved back to the end.</li></ul><h2 id="staged-edits" tabindex="-1">Staged edits <a class="header-anchor" href="#staged-edits" aria-label="Permalink to &quot;Staged edits&quot;">​</a></h2><p>Every change to a section — its content, whether it is switched on, and its position — is held as a staged edit rather than being applied to the storefront immediately. Content drafts are per locale; status and order are per section.</p><p>A section carries <code>hasDraft</code> when it is holding any staged edit. The preview endpoint returns the theme as those edits would leave it, which is what a headless storefront renders to show the merchant their work before it goes live. Publishing promotes every staged edit of a theme and channel at once; discarding throws them all away and leaves the published content untouched.</p><p>A newly created section is created switched off with a staged status, so an empty section is never put in front of shoppers before it has been built.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/appearance/themes/list.html">List themes</a></td><td>Installed and available themes, with the channels each runs on</td></tr><tr><td><a href="/api/rest-api/admin/appearance/themes/detail.html">Get theme</a></td><td>One theme by code</td></tr><tr><td><a href="/api/rest-api/admin/appearance/themes/impact.html">Theme impact</a></td><td>What activating a theme would leave behind</td></tr><tr><td><a href="/api/rest-api/admin/appearance/themes/activate.html">Activate theme</a></td><td>Point channels at a theme</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/list.html">List sections</a></td><td>Sections of a theme for one channel, in render order</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/detail.html">Get section</a></td><td>One section with its translations</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/create.html">Create section</a></td><td>Add a section to a theme and channel</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/update.html">Update section</a></td><td>Write a section&#39;s published values</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/delete.html">Delete section</a></td><td>Remove a section</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/draft.html">Stage edits</a></td><td>Hold options as an unpublished draft</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/status.html">Stage status</a></td><td>Stage a section on or off</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/reorder.html">Stage order</a></td><td>Stage a new render order</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/duplicate.html">Copy section</a></td><td>Copy a section and its content</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/publish.html">Publish</a></td><td>Promote every staged edit</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/discard.html">Discard</a></td><td>Throw away every staged edit</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/fields.html">Section fields</a></td><td>Field schema and current options</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/media.html">Upload media</a></td><td>Store an image or video for a section</td></tr><tr><td><a href="/api/rest-api/admin/appearance/sections/preview.html">Preview</a></td><td>The theme with staged edits applied</td></tr></tbody></table><p>All Appearance endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',17)]))}const f=t(s,[["render",r]]);export{m as __pageData,f as default};
